using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Wine (Linux host) only: installs what the panel needs to run this Windows server - wine, winetricks, Xvfb and
// xdotool - with apt (Debian/Ubuntu) or dnf/yum (Red Hat), and the Windows runtimes listed in Verbs into the service's
// own Wine prefix. Idempotent: anything already present is skipped. Runs before the create/reinstall (host packages,
// so the panel's Wine check passes) and after it (prefix runtimes, once the service user and files exist).
if (!System.OperatingSystem.IsLinux()) return;

// Windows runtimes (winetricks verbs) the server needs inside the prefix. The Unity server and its playfield servers
// run on Wine's built-in runtimes, so none are required today; add verbs here when a game update needs one.
var verbs = new string[] { };

var tools = new (string Command, string[] Apt, string[] Rpm)[]
{
    ("wine", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("wineserver", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("winetricks", new[] { "winetricks" }, new[] { "winetricks" }),
    ("cabextract", new[] { "cabextract" }, new[] { "cabextract" }),
    ("Xvfb", new[] { "xvfb" }, new[] { "xorg-x11-server-Xvfb", "xorg-x11-server-Xvfb.x86_64" }),
    ("xdotool", new[] { "xdotool" }, new[] { "xdotool" }),
};
var apt = Shell("command -v apt-get", out _);
var installer = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
var updated = false;
foreach (var tool in tools)
{
    if (Shell("command -v " + tool.Command, out _)) continue;
    var names = apt ? tool.Apt : tool.Rpm;
    ScriptConsole.WriteLine((object)(tool.Command + " is missing on this host; installing " + string.Join(" or ", names) + "."));
    var installed = names.Any(p => Shell(installer + p, out _));
    if (!installed && apt && !updated)
    {
        updated = Shell("DEBIAN_FRONTEND=noninteractive apt-get update", out _);
        installed = names.Any(p => Shell(installer + p, out _));
    }
    if (!installed || !Shell("command -v " + tool.Command, out _))
        throw new Exception(tool.Command + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
}
Shell("wine --version", out var wineVersion);
ScriptConsole.WriteLine((object)("Wine on this host: " + wineVersion.Trim()));

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/');
// Before the create/reinstall the service files and its run-as configuration do not exist yet.
string user = null;
if (File.Exists(Path.Combine(root, "DedicatedServer", "EmpyrionDedicated.exe")))
{
    try { user = ServiceManagerService.GetServiceCredential(ThisService.ServiceId)?.UserName; }
    catch (FileNotFoundException) { }
}
if (string.IsNullOrEmpty(user) || !Shell("id -u '" + user + "'", out _))
{
    ScriptConsole.WriteLine((object)"The service is not created yet; the Wine prefix is prepared after the files are installed.");
    return;
}
var prefix = Path.Combine(root, ".wine");
// Every Wine call as the service user with the environment the panel starts the server with (root would leave
// root-owned files in the prefix).
var wineEnv = "runuser -u '" + user + "' -- env WINEPREFIX='" + prefix + "' HOME='" + root
              + "' WINEARCH=win64 WINEDEBUG=-all WINEDLLOVERRIDES='mscoree=;mshtml=' ";

// The first start creates the Wine prefix (about a minute), longer than the panel waits for the start that follows
// the create, so that start failed. Create the prefix here; the panel skips it when its marker file is present.
var marker = Path.Combine(prefix, ".tcadmin-initialized");
if (!File.Exists(marker))
{
    ScriptConsole.WriteLine((object)"Creating the Wine prefix (about a minute).");
    if (!Shell(wineEnv + "wineboot -u", out var bootOutput))
        throw new Exception("wineboot failed: " + string.Join("\n", bootOutput.Split('\n').TakeLast(15)));
    Shell(wineEnv + "wineserver -w", out _);
    Shell("runuser -u '" + user + "' -- sh -c \"date -u +%Y-%m-%dT%H:%M:%SZ > '" + marker + "'\"", out _);
    ScriptConsole.WriteLine((object)"The Wine prefix is ready.");
}

if (verbs.Length == 0) return;
// winetricks records every verb it installed in the prefix.
var log = Path.Combine(prefix, "winetricks.log");
var done = File.Exists(log) ? File.ReadAllLines(log).Select(l => l.Trim()).ToHashSet() : new HashSet<string>();
var todo = verbs.Where(v => !done.Contains(v)).ToList();
if (todo.Count == 0)
{
    ScriptConsole.WriteLine((object)("Windows runtimes already installed: " + string.Join(", ", verbs) + "."));
    return;
}
ScriptConsole.WriteLine((object)("Installing " + string.Join(", ", todo) + " into the Wine prefix (a few minutes)."));
var command = wineEnv + "winetricks -q " + string.Join(" ", todo);
if (!Shell(command, out var output))
    throw new Exception("winetricks failed: " + string.Join("\n", output.Split('\n').TakeLast(15)));
Shell(wineEnv + "wineserver -w", out _);
ScriptConsole.WriteLine((object)"Windows runtimes installed.");

bool Shell(string cmd, out string text)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", cmd }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var stderr = process.StandardError.ReadToEndAsync();
        text = process.StandardOutput.ReadToEnd() + stderr.Result;
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

using System;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Console input and the panel's RCON commands for Empyrion: the server's telnet admin console (Tel_Port, always on,
// password = the service's RCON password). "help" lists the commands.
// Empyrion telnet admin console (Tel_Port): plain text lines. When Tel_Pwd is set, the first line the client sends
// is the password (the server prompts "Enter password:"). Replies have no end marker, so a reply is what arrives until the server is quiet for a short gap.
// Blocking socket calls with timeouts (async local functions do not work in panel scripts).
string TelnetClean(byte[] data, int count)
{
    // Drop telnet negotiation (IAC sequences) and carriage returns.
    var sb = new System.Text.StringBuilder();
    var bytes = new System.Collections.Generic.List<byte>(count);
    for (var i = 0; i < count; i++)
    {
        if (data[i] == 255 && i + 1 < count)
        {
            var cmd = data[i + 1];
            if (cmd == 255) { bytes.Add(255); i++; continue; }
            if (cmd >= 251 && cmd <= 254) { i += 2; continue; }
            if (cmd == 250) { while (i < count && !(data[i] == 255 && i + 1 < count && data[i + 1] == 240)) i++; i++; continue; }
            i++; continue;
        }
        if (data[i] != 13 && data[i] != 0) bytes.Add(data[i]);
    }
    return System.Text.Encoding.UTF8.GetString(bytes.ToArray());
}

// Reads until nothing arrives for gapMs (after the first data), or until firstMs pass without any data.
string TelnetRead(System.Net.Sockets.TcpClient client, int firstMs, int gapMs, int maxMs = 30000)
{
    var stream = client.GetStream();
    var buffer = new byte[65536];
    var all = new System.IO.MemoryStream();
    var started = DateTime.UtcNow;
    var last = DateTime.UtcNow;
    while (true)
    {
        var waited = (DateTime.UtcNow - last).TotalMilliseconds;
        var limit = all.Length == 0 ? firstMs : gapMs;
        if (waited >= limit || (DateTime.UtcNow - started).TotalMilliseconds >= maxMs) break;
        if (client.Client.Poll(50000, System.Net.Sockets.SelectMode.SelectRead))
        {
            var n = stream.Read(buffer, 0, buffer.Length);
            if (n <= 0) break;
            all.Write(buffer, 0, n);
            last = DateTime.UtcNow;
        }
    }
    var arr = all.ToArray();
    return TelnetClean(arr, arr.Length);
}

void TelnetSend(System.Net.Sockets.TcpClient client, string line)
{
    var bytes = System.Text.Encoding.UTF8.GetBytes(line + "\r\n");
    client.GetStream().Write(bytes, 0, bytes.Length);
}

System.Net.Sockets.TcpClient TelnetConnect(string address, int port, string password, int timeoutMs)
{
    var client = new System.Net.Sockets.TcpClient();
    try
    {
        if (!client.ConnectAsync(address, port).Wait(timeoutMs)) throw new Exception("no connection to " + address + ":" + port + " within " + timeoutMs + " ms");
        client.NoDelay = true;
        client.SendTimeout = timeoutMs;
        // A busy server (starting, booting a playfield) can take seconds to send its prompt.
        var greeting = TelnetRead(client, 8000, 400);
        var prompted = greeting.IndexOf("password", StringComparison.OrdinalIgnoreCase) >= 0;
        if (prompted && string.IsNullOrEmpty(password)) throw new Exception("the console asks for a password and the service has no RCON password");
        if (!string.IsNullOrEmpty(password))
        {
            // No prompt within the wait: send the password anyway, the server reads it as the first line.
            TelnetSend(client, password);
            var reply = TelnetRead(client, prompted ? 4000 : 8000, 400);
            if (reply.IndexOf("wrong", StringComparison.OrdinalIgnoreCase) >= 0) throw new Exception("the console refused the password");
        }
        return client;
    }
    catch
    {
        client.Dispose();
        throw;
    }
}

string TelnetCommand(System.Net.Sockets.TcpClient client, string command, int firstMs, int gapMs = 500)
{
    TelnetSend(client, command);
    var reply = TelnetRead(client, firstMs, gapMs).Trim('\n', ' ');
    if (reply.StartsWith("Wrong password", StringComparison.OrdinalIgnoreCase)) throw new Exception("the console refused the password");
    return reply;
}


string result;
try
{
    var command = (Globals.Variables.Parse<string>("Command") ?? string.Empty).Trim();
    if (command.Length == 0)
    {
        result = string.Empty;
    }
    else
    {
        // The console listens on every address of the host: the address the panel passes, else the service IP.
        var address = Globals.Variables.Parse<string>("Address");
        if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
        var port = ThisService.RconPort;
        try { var injected = Convert.ToInt32(Globals.Variables.Parse<string>("Port")); if (injected > 0) port = injected; } catch { }
        var password = Globals.Variables.Parse<string>("Password");
        if (string.IsNullOrEmpty(password) && ThisService.Variables.ContainsKey("RconPassword")) password = Convert.ToString(ThisService.Variables["RconPassword"]);
        using (var client = TelnetConnect(address, port, password ?? string.Empty, 4000))
        {
            result = TelnetCommand(client, command, 6000, 700);
        }
        if (result.Length == 0) result = "(no reply)";
    }
}
catch (Exception ex)
{
    result = "Telnet console error: " + ex.Message;
}
Globals.ReturnValue = result;

